#include <vector>
#include <numeric>
#include <cmath>
#include <algorithm>

class Solution {
public:
    long long minMovesToBalanceCircularArray(std::vector<int>& nums) {
        int n = nums.size();
        long long total = 0;
        for (int x : nums) total += x;
        if (total % n != 0) return -1;
        long long target = total / n;
        std::vector<long long> flow(n);
        long long cur = 0;
        for (int i = 0; i < n; ++i) {
            cur += nums[i] - target;
            flow[i] = cur;
        }
        std::sort(flow.begin(), flow.end());
        long long median = flow[n / 2];
        long long moves = 0;
        for (long long f : flow) moves += std::abs(f - median);
        return moves;
    }
};

