function minMovesToBalanceCircularArray(nums) {
    const n = nums.length;
    const total = nums.reduce((a, b) => a + b, 0);
    if (total % n !== 0) return -1;
    const target = total / n;
    const flow = new Array(n);
    let cur = 0;
    for (let i = 0; i < n; i++) {
        cur += nums[i] - target;
        flow[i] = cur;
    }
    flow.sort((a, b) => a - b);
    const median = flow[Math.floor(n / 2)];
    let moves = 0;
    for (const f of flow) moves += Math.abs(f - median);
    return moves;
}
